using System.Reflection;
namespace ImageGuide;
public static class GuidanceSelfTests
{
    public static void Run()
    {
        int passed=0;void Check(string name,Action action){action();passed++;Console.WriteLine("PASS "+name);}var flags=BindingFlags.Instance|BindingFlags.NonPublic;
        GuideForm Form(){var context=SynchronizationContext.Current;try{return new GuideForm{AutoScaleMode=AutoScaleMode.None,ClientSize=ShellGeometry.CanonicalClient};}finally{SynchronizationContext.SetSynchronizationContext(context);}}
        T Field<T>(GuideForm form,string name)=>(T)typeof(GuideForm).GetField(name,flags)!.GetValue(form)!;
        void Call(GuideForm form,string name,params object[] args)=>typeof(GuideForm).GetMethod(name,flags)!.Invoke(form,args);
        Check("guide default primary mode and no automatic job",()=>{using var f=Form();if(!Field<CheckBox>(f,"guidedMode").Checked||Field<bool>(f,"busy")||Field<JobControl?>(f,"job")!=null)throw new Exception("Guide started a job");Call(f,"ContinueGuide");if(Field<int>(f,"step")!=0||Field<JobControl?>(f,"job")!=null)throw new Exception("Guide left supported source path");});
        Check("capabilities derived without preview execution grants",()=>{if(GuidanceState.Capability(1,true,true,false)!="Preview only"||GuidanceState.Capability(9,false,false,false)!="Needs inspection"||GuidanceState.Capability(9,true,true,false)!="Available"||GuidanceState.Capability(9,true,true,true)!="Needs attention")throw new Exception();});
        Check("individual preview removal preserves unrelated choices and Undo",()=>{using var f=Form();var boxes=Field<Dictionary<string,CheckBox>>(f,"previewChoices");boxes["tpm"].Checked=true;boxes["xbox"].Checked=true;Call(f,"RemoveChange","option:tpm");if(boxes["tpm"].Checked||!boxes["xbox"].Checked)throw new Exception();Call(f,"Undo");if(!boxes["tpm"].Checked||!boxes["xbox"].Checked)throw new Exception();});
        Check("service and region individual removal is reversible",()=>{using var f=Form();var services=Field<Dictionary<string,ComboBox>>(f,"previewServices");var region=Field<ComboBox>(f,"previewRegion");services["Spooler"].SelectedItem="Manual";region.SelectedIndex=1;Call(f,"RemoveChange","service:Spooler");if(services["Spooler"].SelectedIndex!=0||region.SelectedIndex!=1)throw new Exception();Call(f,"Undo");if(services["Spooler"].SelectedItem?.ToString()!="Manual")throw new Exception();Call(f,"RemoveChange","region");if(region.SelectedIndex!=0)throw new Exception();Call(f,"Undo");if(region.SelectedIndex!=1)throw new Exception();});
        Check("media and broad goal removal preserves other state",()=>{using var f=Form();var media=Field<CheckBox>(f,"preferEdition");var goals=Field<Dictionary<string,CheckBox>>(f,"goals");media.Checked=true;goals["Updates"].Checked=true;Call(f,"RemoveChange","media:edition");if(media.Checked||!goals["Updates"].Checked)throw new Exception();Call(f,"Undo");if(!media.Checked)throw new Exception();Call(f,"RemoveChange","goal:Updates");if(goals["Updates"].Checked||!media.Checked)throw new Exception();});
        Check("busy guard rejects individual removal and guide navigation",()=>{using var f=Form();var boxes=Field<Dictionary<string,CheckBox>>(f,"previewChoices");boxes["tpm"].Checked=true;typeof(GuideForm).GetField("busy",flags)!.SetValue(f,true);Call(f,"RemoveChange","option:tpm");Call(f,"ContinueGuide");if(!boxes["tpm"].Checked||Field<int>(f,"step")!=0)throw new Exception();});
        Check("guided footer does not route through preview workspaces",()=>{using var f=Form();Field<Button>(f,"next").PerformClick();if(Field<int>(f,"step")!=0)throw new Exception("Guided Next opened unsupported preview");});
        Check("advanced mode keeps all workspace navigation",()=>{using var f=Form();Field<CheckBox>(f,"guidedMode").Checked=false;Call(f,"Go",5);if(Field<int>(f,"step")!=5||Field<List<Button>>(f,"steps").Count!=10)throw new Exception();});
        Check("guided confirmed edition routes only supported build preferences",()=>{using var f=Form();var editions=Field<ComboBox>(f,"editions");editions.Items.Add(new Edition(1,"Home","x64","10.0.26100.1",26100,"Client","Core"));editions.SelectedIndex=0;typeof(GuideForm).GetField("result",flags)!.SetValue(f,new Inspection(1,"C:\\fixture.iso","HASH","now","released","owned",[],[],"Unknown","fixture"));typeof(GuideForm).GetField("guideStage",flags)!.SetValue(f,1);Call(f,"RefreshWorkspaceState");if(!Field<Button>(f,"guideContinue").Text.StartsWith("Confirm selected edition"))throw new Exception("Default edition silently confirmed");Call(f,"ContinueGuide");if(Field<int>(f,"step")!=9||Field<int>(f,"guideStage")!=2)throw new Exception();});
        Check("guide and source page do not overlap",()=>{using var f=Form();_ = f.Handle;void Layout(Control control){control.PerformLayout();foreach(Control child in control.Controls)Layout(child);}for(int i=0;i<3;i++)Layout(f);var guide=Field<TableLayoutPanel>(f,"guideBar");var pages=Field<List<TableLayoutPanel>>(f,"pages");if(guide.Bottom>pages[0].Top||guide.Width>guide.Parent!.ClientSize.Width)throw new Exception($"Guide/page overlap: {guide.Bounds} / {pages[0].Bounds}");});
        Console.WriteLine($"{passed} guided UX tests passed.");
    }
}
